-- Concept-sample Tips & Tricks articles (clearly labeled as samples). Run once, after schema.sql.
insert into public.articles (title, category, read_min, author_label, role_label, excerpt, blocks, image_key, is_sample, created_at) values (
  'Balancing Work and Wellness: Self-Care Tips for Women in Sports Careers', 'Wellness', 5, 'Concept sample', 'Example article written to show the format, not by a real professional',
  'Practical ways to manage the stress and physical demands of a sports career while keeping a healthy work-life balance.',
  '[{"p":"Working in professional sports, especially as a woman, can be incredibly rewarding, but it''s also a fast-paced, high-pressure environment. When you''re constantly managing players'' injuries, coordinating team schedules, and attending to the needs of high-performance athletes, it can be easy to neglect your own wellness."},{"p":"In this article, I''ll discuss my journey to finding balance between my career and personal well-being, along with practical self-care strategies that can be applied to any woman working in the sports industry."},{"h":"Prioritize Physical Activity","p":"I''ve always been active, but working in a physically demanding environment has sometimes made it difficult to prioritize my own fitness. As an athletic trainer, my days revolve around physical care for the players, so it''s easy to forget my own body. Whether it''s a morning walk or a restorative yoga session before bed, physical activity helps me recharge. It''s easy to skip out on self-care when your job demands so much of you, but I''ve found that investing in my health ultimately helps me perform better at work, too."},{"h":"Set Boundaries","p":"Another critical aspect of wellness is setting boundaries, which I''ve struggled with throughout my career. In sports, especially in the competitive environment of professional basketball, there''s often an unspoken expectation to be \"on\" 24/7. But I''ve learned that constantly saying \"yes\" to every request, whether from coaches or players, leads to burnout.\n\nSetting clear boundaries around work hours and learning to say \"no\" has been one of the most effective strategies I''ve used to protect my well-being. This might mean turning off emails after hours or scheduling \"me time\" on my calendar."},{"h":"Mental Health Matters","p":"The mental and emotional side of wellness is just as important as physical health. The stress of working in sports can sometimes feel overwhelming, and I''ve realized that taking care of my mental health is crucial.\n\nFor me, journaling and talking with a therapist has been extremely helpful in managing work-related stress. A lot of the time, I don''t realize how much tension I''m carrying until I take a moment to reflect. Being able to process emotions and thoughts outside of the workplace has helped me maintain a healthier perspective."},{"h":"Build a Support System","p":"Having a network of women who understand the unique challenges I face in sports has been invaluable. I''ve found support through other women in similar roles, and I try to be that support for others as well. Whether it''s swapping advice on how to manage stress or simply sharing experiences, having these relationships makes a huge difference.\n\nUltimately, self-care isn''t a luxury — it''s a necessity. By prioritizing my health and setting boundaries, I''m not only better equipped to handle the demands of my job, but I''m also setting a positive example for the players I work with."}]'::jsonb, 'trainers', true, now() - interval '0 days');
insert into public.articles (title, category, read_min, author_label, role_label, excerpt, blocks, image_key, is_sample, created_at) values (
  'Building a Personal Brand in Sports: How to Stand Out and Get Noticed', 'Branding', 4, 'Concept sample', 'Example article written to show the format, not by a real professional',
  'How to build a strong personal brand through social media, networking, and showcasing what you know.',
  '[{"p":"Your personal brand is how the industry remembers you before you''re even in the room. The good news: you don''t need a huge following. You need a clear point of view and consistency."},{"h":"Get specific","p":"Finish this sentence: \"I help ___ by ___.\" Women who are known for something specific, like game-day content, analytics, or athlete storytelling, get the call when that need comes up."},{"h":"Treat social like a portfolio in motion","p":"Post the work, and the process behind it. Share a lesson from a project, a takeaway from a panel, or a behind-the-scenes look at your craft. Two thoughtful posts a week beats a daily scramble."},{"h":"Network in real time","p":"Every conversation, DM, or panel question is a chance to reinforce what you stand for. Follow up within 48 hours with something useful: an article, an intro, a specific compliment."},{"h":"Share expertise generously","p":"Sharing what you know builds trust faster than any resume line. Answer questions in communities like this one, and you''ll be surprised who''s watching."}]'::jsonb, null, true, now() - interval '1 days');
insert into public.articles (title, category, read_min, author_label, role_label, excerpt, blocks, image_key, is_sample, created_at) values (
  'From Fan to Pro: How to Transition from a Passion for Sports to a Career', 'Career', 4, 'Concept sample', 'Example article written to show the format, not by a real professional',
  'How to turn a lifelong love of sports into a career, whether in management, media, coaching, or behind the scenes.',
  '[{"p":"Loving a sport and building a career around it are two different skill sets, and the second one is learned on purpose."},{"h":"Map the roles you don''t see on TV","p":"Sponsorship, operations, analytics, content, community, partnerships, ticketing. Most entry points live behind the scenes. Browse job boards by function, not just by team."},{"h":"Get proximity early","p":"Volunteer at events, intern relentlessly, and say yes to the unglamorous shifts. Proximity teaches you the industry''s language faster than any course."},{"h":"Turn fandom into insight","p":"Your fandom is an asset. You understand what fans want. Translate that into pitches: a campaign idea, a content series, a better game-day moment."},{"h":"Ask for 15 minutes","p":"People in this industry remember who helped them. A specific, short ask (\"Could I get 15 minutes of your advice on breaking into partnerships?\") gets a yes more often than you''d think."}]'::jsonb, null, true, now() - interval '2 days');
insert into public.articles (title, category, read_min, author_label, role_label, excerpt, blocks, image_key, is_sample, created_at) values (
  'Workplace Confidence: How to Speak Up and Own Your Space in Male-Dominated Environments', 'Confidence', 5, 'Concept sample', 'Example article written to show the format, not by a real professional',
  'Tips for building the confidence to speak up and take up space in male-dominated rooms.',
  '[{"p":"Confidence in rooms that weren''t built with you in mind is a practiced skill, not a personality trait you either have or don''t."},{"h":"Prepare your first sentence","p":"Knowing exactly how you''ll start removes the hesitation of speaking up. Write down your point before the meeting and plan to speak in the first ten minutes."},{"h":"Negotiate like it''s part of the job","p":"Because it is. Come with market data and a specific number, not apologies. Practice out loud with a mentor or friend before the real conversation."},{"h":"Don''t shrink the ask","p":"Cut filler like \"just\" and \"sorry, but.\" Say \"I recommend\" or \"I''d like to propose.\" Direct isn''t rude. It''s respected."},{"h":"Take space, make space","p":"Every time you take up space well, you make it a little easier for the next woman in the room. Then hold the door: credit others'' ideas out loud and sponsor someone coming up behind you."}]'::jsonb, null, true, now() - interval '3 days');
